// optional (opticli leaves nulls out). Named as in opticli's C# code; a name doesn't change once published.

/** A JSON value, as opticli prints it. */
export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

/** A cell of `sql`'s rows: dates are strings, binary is `0x…` hex, long strings are cut unless `full`. */
export type SqlValue = string | number | boolean | null;

/**
 * A property as `get` shows it: its type and value, with what `get` adds for reading (`culture`, `links`,
 * `blockType`, `target`, `blocks`, `personalized`, and `truncated` with the full `length` for a cut value).
 */
export interface PropertyOut {
  /** The property's type: `String`, `XhtmlString`, `ContentArea`, `ContentReference`, ... */
  type: string;
  value: JsonValue;
  /** The language branch the stored value is in (`sv`). */
  culture?: string;
  /** The value was cut short (`full` shows it whole). */
  truncated?: boolean;
  /** The whole value's length, when it was cut. */
  length?: number;
  [decoration: string]: JsonValue | undefined;
}

export interface AccessEntry {
  name: string;
  /** One of `AccessKinds`. */
  kind: AccessKind | (string & {});
  /** Level names (`Describe`): `FullAccess`, or the individual levels. */
  levels: string[];
  /** The stored `AccessLevel` bits. */
  mask: number;
}

/** Entry kinds, from `SecurityEntityType` (stored as `tblContentAccess.IsRole`). */
export type AccessKind = 'user' | 'role' | 'visitorGroup';

/** The effective ACL of an item. */
export interface AccessList {
  /** True when the item has no entries of its own and uses `From`'s. */
  inherited: boolean;
  /** Ref of the item the entries are stored on: the item itself, or the nearest ancestor with its own. */
  from?: string;
  entries: AccessEntry[];
  /** For a "For this page" folder and the content in it: ref of the content that owns the folder. The CMS gives them that content's access rights, so `From` is the owner or where the owner inherits from. */
  assetsOf?: string;
}

/** Result of `access`: the item's effective ACL before and after. */
export interface AccessOutput {
  ref: string;
  guid: string;
  type?: string;
  name?: string;
  /** False for a dry run, and when the change was already in place. */
  saved: boolean;
  dryRun: boolean;
  before: AccessList;
  after: AccessList;
}

export interface AccessView {
  ref: string;
  guid: string;
  type?: string;
  name?: string;
  inherited: boolean;
  from?: string;
  /** The content whose "For this page" folder this is, or holds this item: its access rights apply. */
  assetsOf?: string;
  entries: AccessEntry[];
  /** The content approval sequence publishing goes through, when one applies. */
  approval?: ApprovalSequence;
}

